# ---------- serialize व insert ----------
def js_entry(n, e):
    lines = ['  "%d": {' % n]
    lines.append('    "slug": %s,' % json.dumps(e["slug"], ensure_ascii=False))
    lines.append('    "title_hi": %s,' % json.dumps(e["title_hi"], ensure_ascii=False))
    lines.append('    "title_note": %s,' % json.dumps(e["title_note"], ensure_ascii=False))
    lines.append('    "mg": %d,' % e["mg"])
    lines.append('    "parts": {')
    keys = list(e["parts"].keys())
    for i, k in enumerate(keys):
        comma = "," if i < len(keys)-1 else ""
        lines.append('      "%s": %s%s' % (k, json.dumps(e["parts"][k], ensure_ascii=False), comma))
    lines.append('    }')
    lines.append('  },')
    return "\n".join(lines)

anchor = '  "934": {'
assert data.count(anchor) == 1, "934-anchor count != 1"
block = js_entry(932, E932) + "\n" + js_entry(933, E933) + "\n"
data = data.replace(anchor, block + anchor)

io.open(F, "w", encoding="utf-8").write(data)
print("✅ 932 व 933 entries जुड़ीं। नया आकार:", len(data))

